window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8c2eb8fa4c78a2d8"]={"versions": [{"id": "FIG-8c2eb8fa4c78a2d8", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur ECU-Konfiguration (BSW-Modulbeschreibung / Parameterdefinition) des Diagnostic Event Managers (Dem) gemäß AUTOSAR-Standard. Das Diagramm spezifiziert die Konfigurationscontainer-Struktur zur Auswahl und Zuordnung von Entprell-Algorithmen (Debounce-Algorithmen) zu diagnostischen Ereignissen (<code>DemEventParameter</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Folgende Entitäten und Beziehungen sind modelliert:</p>\n<ul class=\"fig-list\"><li><code>DemEventParameter</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: lowerMultiplicity = 1, upperMultiplicity = 65535): Repräsentiert die Konfigurationsinstanz eines Dem-Ereignisses.\n</li><li><code>DemDebounceAlgorithmClass</code> (<code>EcucChoiceContainerDef</code>, Multiplizität: lowerMultiplicity = 1, upperMultiplicity = 1): Dient als Auswahlcontainer (<code>+subContainer</code>-Komposition ausgehend von <code>DemEventParameter</code>), der genau eine Entprellstrategie vorschreibt.\n</li><li>Als konkrete Auswahlen (<code>+choice</code>-Kompositionen, jeweils mit lowerMultiplicity = 0, upperMultiplicity = 1) stehen zur Verfügung:\n<ul class=\"fig-list\"><li><code>DemDebounceTimeBase</code> (<code>EcucParamConfContainerDef</code>): Zeitbasierte Entprellung.\n</li><li><code>DemDebounceCounterBased</code> (<code>EcucParamConfContainerDef</code>): Zählerbasierte Entprellung.\n</li><li><code>DemDebounceMonitorInternal</code> (<code>EcucParamConfContainerDef</code>): Entprellung intern im überwachenden Software-Monitor bzw. BSW-Modul / Sensor.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell zur Entwurfs- und Generierungszeit. Jedem diagnostischen Ereignis wird bei der ECU-Konfiguration genau ein Entprellmechanismus zugeordnet. Zur Laufzeit steuert diese Festlegung den Qualifizierungsprozess von Fehlermeldungen (Passed / Failed): Entweder führt der Dem die Fehlerfilterung über Timer (<code>DemDebounceTimeBase</code>) bzw. Integrator-Zähler (<code>DemDebounceCounterBased</code>) autonom durch, oder er übernimmt den bereits vorqualifizierten Status direkt aus dem SW-C/BSW-Monitor (<code>DemDebounceMonitorInternal</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die Konfigurationswerkzeuge und den Codegenerator des AUTOSAR Dem. Da <code>DemDebounceAlgorithmClass</code> als <code>EcucChoiceContainerDef</code> mit Multiplizität 1..1 deklariert ist, muss für jedes konfigurierte <code>DemEventParameter</code> zwingend genau eine der drei Sub-Container-Definitionen gewählt werden. Die obere Schranke von 65535 für <code>DemEventParameter</code> definiert die maximale modellierte Anzahl an Dem-Events pro Konfigurationseinheit.</p>"}, {"id": "FIG-0b5b07ca86afed46", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur ECU-Konfiguration (BSW-Modulbeschreibung / Parameterdefinition) des Diagnostic Event Managers (Dem) gemäß AUTOSAR-Standard. Das Diagramm spezifiziert die Konfigurationscontainer-Struktur zur Auswahl und Zuordnung von Entprell-Algorithmen (Debounce-Algorithmen) zu diagnostischen Ereignissen (<code>DemEventParameter</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Folgende Entitäten und Beziehungen sind modelliert:</p>\n<ul class=\"fig-list\"><li><code>DemEventParameter</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: lowerMultiplicity = 1, upperMultiplicity = 65535): Repräsentiert die Konfigurationsinstanz eines Dem-Ereignisses.\n</li><li><code>DemDebounceAlgorithmClass</code> (<code>EcucChoiceContainerDef</code>, Multiplizität: lowerMultiplicity = 1, upperMultiplicity = 1): Dient als Auswahlcontainer (<code>+subContainer</code>-Komposition ausgehend von <code>DemEventParameter</code>), der genau eine Entprellstrategie vorschreibt.\n</li><li>Als konkrete Auswahlen (<code>+choice</code>-Kompositionen, jeweils mit lowerMultiplicity = 0, upperMultiplicity = 1) stehen zur Verfügung:\n<ul class=\"fig-list\"><li><code>DemDebounceTimeBase</code> (<code>EcucParamConfContainerDef</code>): Zeitbasierte Entprellung.\n</li><li><code>DemDebounceCounterBased</code> (<code>EcucParamConfContainerDef</code>): Zählerbasierte Entprellung.\n</li><li><code>DemDebounceMonitorInternal</code> (<code>EcucParamConfContainerDef</code>): Entprellung intern im überwachenden Software-Monitor bzw. BSW-Modul / Sensor.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell zur Entwurfs- und Generierungszeit. Jedem diagnostischen Ereignis wird bei der ECU-Konfiguration genau ein Entprellmechanismus zugeordnet. Zur Laufzeit steuert diese Festlegung den Qualifizierungsprozess von Fehlermeldungen (Passed / Failed): Entweder führt der Dem die Fehlerfilterung über Timer (<code>DemDebounceTimeBase</code>) bzw. Integrator-Zähler (<code>DemDebounceCounterBased</code>) autonom durch, oder er übernimmt den bereits vorqualifizierten Status direkt aus dem SW-C/BSW-Monitor (<code>DemDebounceMonitorInternal</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die Konfigurationswerkzeuge und den Codegenerator des AUTOSAR Dem. Da <code>DemDebounceAlgorithmClass</code> als <code>EcucChoiceContainerDef</code> mit Multiplizität 1..1 deklariert ist, muss für jedes konfigurierte <code>DemEventParameter</code> zwingend genau eine der drei Sub-Container-Definitionen gewählt werden. Die obere Schranke von 65535 für <code>DemEventParameter</code> definiert die maximale modellierte Anzahl an Dem-Events pro Konfigurationseinheit.</p>"}], "trans": [{"from": "FIG-8c2eb8fa4c78a2d8", "to": "FIG-0b5b07ca86afed46", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
